package com.qualitypilot.campaignlab.execution;
import jakarta.persistence.*; import java.time.Instant;
@Entity public class NodeExecution{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="run_id")private String runId;@Column(name="user_id")private String userId;@Column(name="node_key")private String nodeKey;@Column(name="node_type")private String nodeType;private String result;@Column(name="branch_label")private String branchLabel;@Column(name="executed_at")private Instant executedAt;@Column(name="resume_at")private Instant resumeAt;protected NodeExecution(){}public NodeExecution(String r,String u,String key,String type,String result,String branch,Instant at,Instant resume){runId=r;userId=u;nodeKey=key;nodeType=type;this.result=result;branchLabel=branch;executedAt=at;resumeAt=resume;}public Long getId(){return id;}public String getRunId(){return runId;}public String getUserId(){return userId;}public String getNodeKey(){return nodeKey;}public String getNodeType(){return nodeType;}public String getResult(){return result;}public String getBranchLabel(){return branchLabel;}public Instant getExecutedAt(){return executedAt;}public Instant getResumeAt(){return resumeAt;}}
